(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["cs"] = {"ui":{"skip":"Přeskočit na obsah","back":"← Zpět na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hledat jazyk","lang.none":"Žádný jazyk neodpovídá","lang.notYet":"{name} zatím není přeloženo","theme.aria":"Přepnout mezi světlým a tmavým motivem","theme.toLight":"Přepnout na světlý motiv","theme.toDark":"Přepnout na tmavý motiv","index.title":"AI-gile: tvůj AI vývojářský tým na jedné tabuli","index.description":"AI-gile je kanbanová tabule pro týmy AI programátorů. Pracují, zatímco spíš; ty dostaneš jednu krátkou hromádku věcí k rozhodnutí, vyzkoušení a schválení.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvůj AI vývojářský tým na jedné&nbsp;tabuli.","hero.alpha":"🐣 Uzavřená pre-alfa","hero.alphaTitle":"Brzy a nehotové: díky, že to zkoušíš!","hero.lede":"Staví, zatímco spíš. Ráno tě čeká jedna krátká hromádka: pár otázek, pár věcí k vyzkoušení, jeden dva fialové diamanty. Klik, schváleno, zpátky ke kávě.","dl.windows":"Aplikace pro Windows","dl.browser":"Spustit v prohlížeči","dl.soon":"Brzy","dl.notify":"🔔 Dej mi vědět, až se otevře","dl.notifySmall":"Alfa nebo beta","hero.secondary":"Agile, jen tým nepotřebuje stand-up u kávy. (Stand-upy ale dělá stejně.)","pitch.h2":"AI-gile na tolik slov, kolik chceš","pitch.lede":"Vyber délku, od jednoho slova po 144. Každá délka je vlastní popis napsaný přesně pro ni. Posuň jezdec nebo použij šipky.","pitch.rangeLabel":"Délka ve slovech","pitch.dice":"🎲 další verze","pitch.words.one":"{n} slovo","pitch.words.few":"{n} slova","pitch.words.many":"{n} slova","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.few":"{n} písmena","pitch.letters.many":"{n} písmena","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","pitch.chars.other":"{n} znaků","count.line.html.one":"{n} karta právě teď na tabuli","count.line.html.few":"{n} karty právě teď na tabuli","count.line.html.many":"{n} karty právě teď na tabuli","count.line.html.other":"{n} karet právě teď na tabuli","features.aria":"Co umí","f.pile.h":"Jedna hromádka pro tebe","f.pile.html":"<b>Pro tebe</b> shromažďuje všechno, co čeká na tebe, napříč všemi projekty: otázky, věci k vyzkoušení, úkoly jen pro člověka. Tvoje fronta říká, co je na řadě a jak dlouho to potrvá.","f.sleep.h":"Týmy, které pracují, zatímco spíš","f.sleep.p":"Každý projekt má vedoucího a tým AI agentů. Okomentuj kartu a tým se probudí, odvede práci a vrátí ti ji s kroky, které zvládne i unavený člověk.","f.tester.h":"Nejdřív to zkontroluje AI tester","f.tester.p":"Než se k tobě cokoli dostane, tester projde kroky v kopii aplikace a ukáže, co viděl, se snímkem obrazovky. Prolistuj ty úspěšné a schval je jedním klikem.","f.proof.h":"Důkazy, ne sliby","f.proof.p":"Každé předání ukazuje, co se změnilo: soubory, rozdíly, snímky obrazovky. Žádné otevírání každé aplikace, abys zjistil, jestli je hotovo.","f.chat.h":"Chat s tvými vedoucími","f.chat.p":"Lišta jako na Discordu: jedna ikona na projekt, fialové diamanty u toho, co potřebuje tebe. Napiš vedoucímu nápad; promění ho v karty a plán s tlačítkem ✅ Go.","f.tidy.h":"Udržuje si pořádek","f.tidy.p":"Související karty se slijí v jednu, zmatené názvy se opraví a kontrola tokenů drží kód štíhlý. Méně věcí k přepínání, méně k přemýšlení.","f.private.h":"Tvoje, na tvém počítači","f.private.li1":"Tabule běží na tvém vlastním stroji a odpovídá jen tobě.","f.private.li2":"Soukromé zprávy mezi lidmi jsou šifrované end-to-end.","f.private.li3":"Žádné účty, žádné sledování, žádné cookies.","f.lang.h":"Ve tvém jazyce","f.lang.p":"Přes 120 jazyků, od nizozemštiny, velštiny a japonštiny po pirátštinu, Yodu a klingonštinu, s rychlým přepnutím zpět do angličtiny kvůli vývojářským slovům.","tl.aria":"Časová osa od prvního rozhovoru po plán dalšího vývoje","tl.h2":"Od prvního chatu k tomu, co bude dál","tl.lede":"Skutečná data a časy ve tvém časovém pásmu. Po dnešku je to plán, bez slíbených termínů.","tl.today":"Dnes","tl.planned":"plánováno","tl.cards.one":"{n} karta","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty","tl.cards.other":"{n} karet","join.h2":"Přidej se","join.lede":"AI-gile staví malý člověk a velké množství trpělivých agentů. Zatím je soukromé, v uzavřené alfě mezi přáteli. Chceš si to vyzkoušet, až se otevře?","join.btn":"Zaregistrovat zájem","join.small":"Napíšeme ti e-mail, nic jiného","footer.tag":"AI-gile. Žádné sledování, žádné cookies, žádná stand-up káva.","footer.licence":"Firemní licence","footer.status":"Stav","form.sending":"Odesílám…","form.failed":"Nepovedlo se: zkus to později.","form.offline":"AI-gile se nepodařilo zastihnout: zkus to později.","interest.title":"AI-gile: dej mi vědět, až se otevře alfa","interest.description":"Nech nám e-mail a dozvíš se, kdy se otevře uzavřená alfa nebo beta AI-gile.","interest.h1":"🔔 Dej mi vědět, až se otevře","interest.lede":"AI-gile je v uzavřené pre-alfě. Nech nám e-mail a napíšeme ti jednou, až pro tebe bude místo.","interest.email":"Tvůj e-mail","interest.which":"Které testování?","interest.alpha":"Uzavřená alfa: brzy, hrubé, hodně změn","interest.beta":"Beta: stabilnější, později","interest.both":"Obojí, co přijde dřív","interest.submit":"Zapsat mě na seznam","interest.thanks":"Díky! Jsi na seznamu.","interest.kept":"Uchováváme jen tvůj e-mail a vybrané testování, jen pro tento seznam. Žádný newsletter, žádné sledování.","licence.title":"AI-gile: firemní licence","licence.description":"Používáš AI-gile ve firmě? Požádej o bezplatnou firemní licenci.","licence.h1":"📜 Firemní licence","licence.lede":"Používáš AI-gile v práci? Napiš nám, kdo jsi a co děláš. Pokud to dělá něco dobrého, licence je zdarma.","licence.company":"Firma","licence.website":"Web","licence.what":"Čím se zabýváš","licence.how":"Jak to pomáhá světu","licence.email":"E-mail","licence.submit":"Odeslat žádost","licence.thanks":"Díky! Odpovíme e-mailem.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Klid","status.checking":"Kontroluji…","status.offline":"Službu stavu se právě nedaří zastihnout (zkouším znovu)","status.updated":"aktualizováno {ago}","status.justNow":"právě teď","status.min":"před {n} min","status.hours":"před {n} h","status.days":"před {n} d","live.h2":"Sledujte, jak se to staví, živě","live.caption":"Každá karta je skrytá: vidíte tvar práce, ne slova.","live.watching.one":"živě: {n} sleduje","live.watching.other":"živě: {n} sledují","live.offline":"Živá tabule si dává pauzu. Zkuste to brzy znovu.","live.cols":"Backlog|K udělání|Rozpracováno|Tým kontroluje|Čeká na tvůj test|Pro tým|Hotovo","live.last.now":"Poslední karta přesunuta právě teď","live.last.min.one":"Poslední karta přesunuta před {n} min","live.last.min.other":"Poslední karta přesunuta před {n} min","live.last.hour.one":"Poslední karta přesunuta před {n} hodinou","live.last.hour.other":"Poslední karta přesunuta před {n} hodinami","live.last.day.one":"Poslední karta přesunuta před {n} dnem","live.last.day.other":"Poslední karta přesunuta před {n} dny"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegováno."]},{"n":2,"texts":["Robotický kanban.","Agenti, uspořádaně.","Nápady, postavené."]},{"n":3,"texts":["Kanban pro roboty.","Z nápadů funkce.","Agentní kanban zdarma."]},{"n":5,"texts":["Kanbanová tabule řízená AI agenty.","Ty píšeš karty. Agenti staví.","Zdarma, lokální, otestované, trochu praštěné."]},{"n":8,"texts":["Kanbanová tabule zdarma, na které pracují AI agenti.","Napiš nápad. Agenti ho postaví. Ty ho schválíš.","Agile pro jednoho člověka a spoustu trpělivých robotů."]},{"n":13,"texts":["Kanbanová tabule na tvém počítači, kde karty zpracovávají AI agenti.","Napiš nápad. Tým agentů ho postaví. Pak ho zkontroluje tester a ty řekneš ano.","Zdarma, bez účtů, bez sledování: tabule, pár robotů a ty ve vedení."]},{"n":21,"texts":["AI-gile je kanbanová tabule pro práci s AI agenty, kteří programují. Oni berou karty, ty je zkoušíš a schvaluješ.","Každý projekt dostane vedoucího a tým AI agentů. Okomentuj kteroukoli kartu a tým se hned pustí do práce.","Osobní tabule úkolů zdarma, která běží na tvém vlastním počítači. Pracují na ní roboti. Ano říká ten pravý: ty."]},{"n":34,"texts":["Nápady dáváš na tabuli. Tým AI agentů z nich vyrobí fungující funkce, otestuje je a vrátí ti je s kroky k vyzkoušení. Nic se nepočítá jako hotové, dokud to neřekneš ty.","AI-gile je domácí kanbanová tabule, kterou Rich postavil s velkou pomocí agentů, jež dnes sama řídí. Je zdarma, běží na tvém počítači a sdílí se s přáteli, neprodává se.","Představ si obyčejnou kanbanovou tabuli se sloupci od Backlogu po Hotovo, jenže karty si berou AI agenti. Hlásí postup, ptají se, když uvíznou, a vždycky čekají na tvůj palec nahoru."]},{"n":55,"texts":["AI-gile je kanbanová tabule, kde tým tvoří AI agenti. Každý projekt má vedoucího, který plánuje práci, a pomocníky, kteří ji staví. Když je funkce hotová, AI tester ji vyzkouší a udělá snímek obrazovky, pak přistane na tvé hromádce. Schval ji, nebo napiš komentář a oni ji přepracují.","Začalo to jako způsob, jak si jeden člověk hlídal spoustu AI programátorských relací najednou, a vyrostla z toho pořádná tabule. Běží na tvém stroji, nepotřebuje účet a nemá žádné sledování. Pro přátele a zvědavce je zdarma. Také je nedodělané, takže čekej hrubé hrany a občasné překvapení.","Tady je poctivá verze. Nápady pořád musíš mít ty a výsledky pořád musíš kontrolovat ty. AI-gile dělá všechno mezi tím: drží karty v pořádku, probudí správného agenta, když přidáš komentář, ukáže přesně, co se změnilo, a všechno to složí do jedné krátké hromádky pro tebe."]},{"n":89,"texts":["AI-gile je kanbanová tabule zdarma, kterou provozuješ na vlastním počítači. Místo lidí má každý projekt tým AI agentů: vedoucího, který tvé nápady mění v karty a plán, a pomocníky, kteří si karty berou podle priority. Když je něco postavené, AI tester projde testovací kroky a ukáže ti, co viděl. Potom to čeká na jedné hromádce nazvané Pro tebe. Buď to schválíš, nebo napíšeš komentář a tým to zkusí znovu. Do sloupce Hotovo se nic nedostane bez tebe.","Pár věcí, které bys nečekal. Noční hlídka doplňuje sloupec K udělání, zatímco spíš, a vybírá karty, které od tebe nepotřebují žádnou odpověď. Počítadlo tokenů ukazuje, kolik agenti spotřebovali dnes a tento týden, a Režim bez tokenů jim řekne, ať přestanou utrácet. Můžeš psát přátelům a soukromé zprávy jsou šifrované end-to-end. Tabule mluví zhruba 120 jazyky, včetně nizozemštiny, vlámštiny, pirátštiny a klingonštiny. Nic z toho nestojí ani korunu a nikdo se ti to ani nesnaží prodat.","AI-gile je malý osobní projekt, žádná firma. Rich chtěl opečovávat několik AI programátorských projektů, aniž by musel otevírat každou aplikaci a kontrolovat je, tak mu s agenty postavili tabuli, a pak na ní postavili zbytek sebe sama. Je v uzavřené pre-alfě, což znamená, že funguje, většinou, pro hrstku přátel. Není tu žádný ceník, žádný newsletter a žádný plán růstu. Zní to užitečně? Až se to trochu víc otevře, můžeš požádat o vyzkoušení."]},{"n":144,"texts":["AI-gile je kanbanová tabule pro jednoho člověka a spoustu AI agentů. Běží na tvém vlastním počítači a je úplně zdarma. Přidáváš projekty a každý projekt dostane vedoucího a malý tým. S vedoucím si píšeš, trochu jako na Discordu, popíšeš nápad; vedoucí z něj udělá karty a plán a pak čeká, až stiskneš Go. Tým zpracovává karty podle priority pomocí jednoduchého příkazového řádku vytvořeného pro jazykové modely. Než se cokoli vrátí k tobě, AI tester projde kroky v kopii aplikace a přiloží snímek obrazovky. Hotová práce přistane na tvé hromádce se změněnými soubory a rozdílem. Buď ji schválíš, nebo necháš komentář, tým se probudí a zkusí to znovu. Kartu do Hotovo může přesunout jen ty. Žádné účty, žádné sledování, žádné cookies: všechno zůstává u tebe doma, na tvém počítači, a nic se neplatí.","Den s AI-gile, zhruba. Večer necháš pár komentářů: tohle tlačítko je na špatném místě, tenhle seznam by měl být seřazený, mohli bychom mít tmavý režim. Jdeš spát. Agenti si komentáře přečtou, provedou změny, otestují je a vrátí ti je. Když v K udělání dojdou karty, noční hlídka ho doplní z backlogu kartami, které od tebe nepotřebují odpověď. Ráno čeká jedna krátká hromádka: pár otázek a pár věcí k vyzkoušení, každá s kroky, které zvládne i rozespalý člověk, a se snímkem, jak to funguje. Proklikáš se, dobré schválíš a zbytek pošleš zpátky. Počítadlo tokenů ukáže, co to všechno stálo, a Režim bez tokenů je tu pro skromnější týdny. Pak si dáš snídani, u které agenti zatím pomoct neumějí.","Nejdřív, čím AI-gile není. Není to startup, není na prodej a nikdo neshromažďuje tvoje data. Je to bezplatná tabule, která běží na tvém počítači, bez účtů, bez sledování a bez cookies. A čím je: jedním úhledným místem, kde vidíš všechny AI programátorské projekty najednou, s týmem agentů, který dělá karty, a s tebou, který rozhoduješ. Slučuje související karty, opravuje zmatené názvy a hlídá, aby kód zůstal štíhlý. Mluví zhruba 120 jazyky, od nizozemštiny a vlámštiny po pirátštinu a klingonštinu. Přátelé si mohou psát, soukromě a šifrovaně. Postavil ji Rich s velkým počtem trpělivých agentů, většinou za pomoci sebe sama. Je v uzavřené pre-alfě, takže místy drhne. Pokud ti to zní jako zábava, požádej hezky a třeba se dostaneš dovnitř dřív."]}],"quips":{"1":"Jedno slovo. Odvážné. Možná příliš odvážné.","3":"Tři slova. Už teď poctivější než většina stránek o produktech.","8":"Osm slov. Pořád kratší než stand-up.","21":"Délky jsou mimochodem story pointy. Samozřejmě, že jsou.","55":"Padesát pět slov. Zatímco jsi to četl, dokončily se dvě karty.","144":"To je ta dlouhá. Žádná 233 neexistuje. Agenti šli spát."}},"timeline":{"first-idea.name":"První nápad","first-idea.line":"Úplně první rozhovor, ještě než existoval jakýkoli kód.","first-board.name":"První tabule","first-board.line":"Tabule, která sleduje vlastní stavbu: karty, sloupce, přetahování, projekty.","team-roles.name":"Tým a role","team-roles.line":"Profily agentů, šablony týmů, prostory a kdo co dělá.","install.name":"Instalace a vydání","install.line":"Zip, který si přítel nainstaluje, samoaktualizace, kanály a návrat zpět.","usage-saver.name":"Šetření spotřeby","usage-saver.line":"Měř, kolik běhy stojí, drž kód štíhlý, šetři svůj limit.","friends.name":"Přátelé a sdílení","friends.line":"Soukromé zprávy, šifrované předávání, pozvánky, role a sdílené projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovém souboru, nejdřív nizozemština a vlámština.","ai-tester.name":"AI tester","ai-tester.line":"Tester nejdřív zkontroluje každé předání a ukáže, co viděl.","website.name":"Web","website.line":"aigile.lol, upoutávka a tato časová osa.","streaming.name":"Chat a streamování","streaming.line":"Discord, Twitch, OBS, streamerský režim, GIFy a emoji.","no-ai.name":"Edice bez AI","no-ai.line":"Tabule pro lidi, kteří programují bez AI, a veřejné tabule.","night-watch.name":"Noční hlídka","night-watch.line":"Hlídač a Scrum Master drží týmy při práci, zatímco spíš.","p-more.name":"Všechno ostatní","p-more.line":"Menší nápady, které čekají na svou řadu.","p-android.name":"Telefon a Android","p-android.line":"Dostaň se k tabuli z telefonu, pak nativní aplikace pro Android.","p-release.name":"Alfa a dál","p-release.line":"Uzavřená alfa, živý web, pak beta.","p-languages.name":"Další jazyky","p-languages.line":"Více než sto jazyků a režim ponoření pro studenty.","p-engines.name":"Další AI motory","p-engines.line":"Vyber Clauda, Codex nebo Gemini pro každého agenta.","p-pro.name":"Profesionální praxe","p-pro.line":"Štítky rizika, brány pro sloučení, karty incidentů a ochranné zábrany.","p-self.name":"Péče o tebe","p-self.line":"Režim únavy, připomínky péče o sebe a 4:20.","p-servers.name":"Servery a růst","p-servers.line":"Globální nastavení serveru, role a plánování růstu.","p-livestream.name":"Streamovací extra","p-livestream.line":"Twitch chat, vlastní emoji a veřejný živý náhled."},"words":{"button":"📖 Vývojářská slova","h":"📖 Vysvětlení vývojářských slov","intro":"Slova, která používají vývojáři (a AI týmy), srozumitelně.","search":"Hledat slovo…","none":"Žádné slovo tomu neodpovídá.","close":"Zavřít","list":[{"id":"backlog","word":"Backlog","text":"Nápady a práce, které ještě nejsou naplánované. Nic z toho se nedělá, dokud to nepřejde do K udělání."},{"id":"sprint","word":"Sprint","text":"Krátký úsek práce (často týden nebo dva) s dohodnutou sadou karet, které je třeba dokončit.","also":["sprinty","sprintu","sprintů","sprintem","sprintech"]},{"id":"standup","word":"Stand-up","text":"Rychlý check-in: co každý člen týmu udělal, co bude dělat dál a co ho brzdí.","also":["standup","stand-upy","stand-upu","stand-upů","standupy"]},{"id":"bug","word":"Bug","text":"Něco, co nefunguje tak, jak by mělo.","also":["bugy","bugu","bugů","bugem"]},{"id":"test","word":"Test","text":"Vyzkoušení hotové práce před přijetím: dělá to, co se chtělo?","also":["testy","testu","testů","testování","testovat","otestuješ","otestovat"],"noTip":1},{"id":"commit","word":"Commit","text":"Uložený snímek kódu s krátkou poznámkou o tom, co se změnilo. Vždy se k němu můžeš vrátit.","also":["commity","commitu","commitů","commitem"]},{"id":"push","word":"Push","text":"Poslání uložených snímků (commitů) z tohoto počítače na GitHub, aby byly zálohované a sdílené."},{"id":"branch","word":"Branch","text":"Samostatná linie práce v kódu, aby šlo dělat změny, aniž by se sáhlo na hlavní verzi.","also":["branche","branch","větev","větve"]},{"id":"merge","word":"Merge","text":"Sloučení změn z branche zpět do hlavní verze."},{"id":"repo","word":"Repo","text":"Složka projektu s kódem a celou historií commitů, obvykle uložená i na GitHubu.","also":["repozitář","repa","repu"]},{"id":"refactor","word":"Refaktor","text":"Uklizení kódu beze změny toho, co dělá: menší soubory, jasnější názvy, méně opakování."},{"id":"deploy","word":"Deploy","text":"Nasazení nové verze ostře, například na server, kde ji lidé používají."},{"id":"kanban","word":"Kanban","text":"Board se sloupci (K udělání, Rozpracováno, Hotovo), kde karty putují zleva doprava podle toho, jak práce postupuje."},{"id":"wip","word":"WIP limit","text":"Rozpracovaná práce: nejvíc karet, které má sloupec obsahovat, aby tým věci dokončoval, než začne další.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Žádost o zkontrolování a sloučení změn z branche do hlavní verze.","also":["PR"]},{"id":"hook","word":"Hook","text":"Malý příkaz, který se sám spustí v určitou chvíli, např. při startu relace AI, aby tým slyšel tvoje komentáře.","also":["hooky","hooku","hooků"]},{"id":"token","word":"Token","text":"Jednotka, v níž se počítá využití AI: zhruba pár písmen přečteného nebo napsaného textu. Méně tokenů, víc zbývá z tarifu.","also":["tokeny","tokenů","tokenu","tokenech"]},{"id":"agent","word":"Agent","text":"AI, která pracuje samostatně na úkolu: čte kód, dělá změny, spouští kontroly a hlásí se zpět.","also":["agenti","agenta","agentů"]}]}};
